import{c as a,Q as e,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const c=JSON.parse('{"title":"InitBuffer","description":"","frontmatter":{},"headers":[{"level":1,"title":"InitBuffer","slug":"initbuffer"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TPipe/InitBuffer.md","filePath":"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TPipe/InitBuffer.md"}'),d={name:"api/SIMD-API/基础API/资源管理/Pipe和Que框架/TPipe/InitBuffer.md"};function l(i,t,p,r,u,o){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="initbuffer" tabindex="-1">InitBuffer <a class="header-anchor" href="#initbuffer" aria-label="Permalink to &quot;InitBuffer&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于为TQue等队列和TBuf分配内存。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>为TQue等队列分配内存</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class T&gt;</span></span>
<span class="line"><span>__aicore__ inline bool InitBuffer(T&amp; que, uint8_t num, uint32_t len)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 为TQue等队列分配内存，且开发者可以自定义内存的地址信息，地址信息包含起始地址和长度。</span></span>
<span class="line"><span>template &lt;class T, class U, class V, class... Addrs&gt;</span></span>
<span class="line"><span>__aicore__ inline bool InitBuffer(T&amp; que, const Std::tuple&lt;U, V&gt;&amp; addr0, const Addrs&amp;... addrs)</span></span></code></pre></div></li><li><p>为TBuf分配内存</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;TPosition bufPos&gt;</span></span>
<span class="line"><span>__aicore__ inline bool InitBuffer(TBuf&lt;bufPos&gt;&amp; buf, uint32_t len)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> bool InitBuffer(T&amp; que, uint8_t num, uint32_t len) 原型定义模板参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>队列的类型，支持取值TQue、TQueBind、TSCM。</td></tr></tbody></table><p><strong>表 2</strong> bool InitBuffer(T&amp; que, uint8_t num, uint32_t len) 原型定义参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>que</td><td>输入</td><td>需要分配内存的TQue等对象。</td></tr><tr><td>num</td><td>输入</td><td>分配内存块的个数。double buffer功能通过该参数开启：num设置为1，表示不开启double buffer；num设置为2，表示开启double buffer。</td></tr><tr><td>len</td><td>输入</td><td>每个内存块的大小，单位为字节。当传入的len不满足32字节对齐时，API内部会自动向上补齐至32字节对齐，后续的数据搬运过程会涉及非对齐处理。</td></tr></tbody></table><p><strong>表 3</strong> bool InitBuffer(T&amp; que, const Std::tuple&amp; addr0, const Addrs&amp;... addrs) 原型定义模板参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>T</td><td>队列的类型，支持取值TQue、TQueBind。</td></tr><tr><td>U</td><td>起始地址的类型。类型为整型。</td></tr><tr><td>V</td><td>长度的类型。类型为整型。</td></tr><tr><td>Addrs...</td><td>tuple形式的地址信息，包含起始地址和长度。</td></tr></tbody></table><p><strong>表 4</strong> bool InitBuffer(T&amp; que, const Std::tuple&amp; addr0, const Addrs&amp;... addrs) 原型定义参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>que</td><td>输入</td><td>需要分配内存的TQue等对象。</td></tr><tr><td>addr0</td><td>输入</td><td>分配内存块的地址信息，结构为起始地址和长度。</td></tr><tr><td>addrs</td><td>输入</td><td>格式为tuple的地址信息列表，tuple内的元素个数须为2，即起始地址和长度。</td></tr></tbody></table><p><strong>表 5</strong> InitBuffer(TBuf&lt;bufPos&gt;&amp; buf, uint32_t len)原型定义模板参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>bufPos</td><td>TBuf所在的逻辑位置，TPosition类型。</td></tr></tbody></table><p><strong>表 6</strong> InitBuffer(TBuf&lt;bufPos&gt;&amp; buf, uint32_t len)原型定义参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>buf</td><td>输入</td><td>需要分配内存的TBuf对象。</td></tr><tr><td>len</td><td>输入</td><td>为TBuf分配的内存大小，单位为字节。当传入的len不满足32字节对齐时，API内部会自动向上补齐至32字节对齐，后续的数据搬运过程会涉及非对齐处理。</td></tr></tbody></table><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>InitBuffer申请的内存会在TPipe对象销毁时通过析构函数自动释放，无需手动释放。</li><li>如果需要重新分配InitBuffer申请的内存，可以调用<a href="./Reset.html">Reset</a>，再调用InitBuffer接口。</li><li>一个kernel中所有使用的Buffer数量之和不能超过64。</li><li>自定义地址InitBuffer方式分配不建议与不指定地址的混用，可能会导致内存冲突。</li></ul><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>返回Buffer初始化的结果。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 为TQue分配内存，分配内存块数为2，每块大小为128字节</span></span>
<span class="line"><span>AscendC::TPipe pipe; // Pipe内存管理对象</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VECOUT, 2&gt; que; // 输出数据队列管理对象，TPosition为VECOUT</span></span>
<span class="line"><span>uint8_t num = 2;</span></span>
<span class="line"><span>uint32_t len = 128;</span></span>
<span class="line"><span>pipe.InitBuffer(que, num, len);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 为TQue分配内存，开发者自定义内存的地址信息，分别为[0, 1024], [2048, 4096], [8192, 12288]</span></span>
<span class="line"><span>AscendC::TPipe pipe; // Pipe内存管理对象</span></span>
<span class="line"><span>AscendC::TQue&lt;AscendC::TPosition::VECOUT, 1&gt; que; // 输出数据队列管理对象，TPosition为VECOUT</span></span>
<span class="line"><span>auto addr0 = Std::make_tuple(0, 1024);</span></span>
<span class="line"><span>auto addr1 = Std::make_tuple(2048, 2048);</span></span>
<span class="line"><span>auto addr2 = Std::make_tuple(8192, 4096);</span></span>
<span class="line"><span>pipe.InitBuffer(que, addr0, addr1, addr2);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 为TBuf分配内存，分配长度为128字节</span></span>
<span class="line"><span>AscendC::TPipe pipe;</span></span>
<span class="line"><span>AscendC::TBuf&lt;AscendC::TPosition::A1&gt; buf; // 输出数据管理对象，TPosition为A1</span></span>
<span class="line"><span>uint32_t len = 128;</span></span>
<span class="line"><span>pipe.InitBuffer(buf, len);</span></span></code></pre></div>`,26)])])}const f=a(d,[["render",l]]);export{c as __pageData,f as default};
